fn solve(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate enough space: original length + max suffix length (2).
    let mut result = Vec::with_capacity(s.len() + 2);

    // Copy the original characters.
    result.extend(s.iter());

    // If the last character is 's', append "es", otherwise append "s".
    if *s.last().unwrap() == 's' {
        result.push('e');
        result.push('s');
    } else {
        result.push('s');
    }

    result
}

// -- Example usage and tests --
fn main() {
    let word1: Vec<char> = "bus".chars().collect();
    let plural1 = solve(&word1);
    assert_eq!(plural1.iter().collect::<String>(), "buses");

    let word2: Vec<char> = "cat".chars().collect();
    let plural2 = solve(&word2);
    assert_eq!(plural2.iter().collect::<String>(), "cats");

    println!("All tests passed!");
}